<script setup lang="ts">
import {computed,ref} from 'vue';
import type {InfoFields} from '../../shared/api/meeting-info';
import type {Person,Category} from '../../shared/api/meeting-options';
import type {CommandState} from '../../shared/composables/useCommand';
const props=defineProps<{presentation?:'drawer'|'final';value:InfoFields;dirty:boolean;busy:boolean;blocked:boolean;state:CommandState;operation:string|null;conflict:boolean;conflictValue?:InfoFields|null;conflictToken?:string|null;canConfirm:boolean;categories:readonly Category[];people:readonly Person[];rosterNames?:Record<string,string>;optionsBusy:boolean;optionsError:string|null;categoryMore:boolean;peopleMore:boolean;error:string|null;storageStatus:string}>();
const emit=defineEmits<{edit:[value:InfoFields];save:[];confirm:[];retry:[];reload:[];reapply:[];discard:[];search:[query:string];categories:[more:boolean];people:[query:string];close:[]} >();
const query=ref(''),external=ref(''),peopleTab=ref('internal'),peopleDialog=ref<HTMLDialogElement>();
const unresolved=computed(()=>['PREPARED','SENDING','UNCERTAIN','DENIED'].includes(props.state));
function update(key:keyof InfoFields,value:unknown){emit('edit',{...props.value,[key]:value});}
function input(key:'name'|'summary'|'category'|'occurredOn',event:Event){const value=(event.target as HTMLInputElement).value;update(key,value===''?null:value);}
function addPerson(person:Person){if(person.active&&!props.value.rosterDraftIds.includes(person.stableId))update('rosterDraftIds',[...props.value.rosterDraftIds,person.stableId]);}
function addExternal(){if(external.value.trim()){update('externalRosterNames',[...(props.value.externalRosterNames??[]),external.value]);external.value='';}}
</script>
<template>
 <section class="info-editor" :class="{'info-editor-final':presentation==='final'}" aria-labelledby="info-editor-heading">
  <h2 id="info-editor-heading">编辑会议信息</h2>

  <p v-if="blocked" role="alert">恢复记录暂无法读取，已暂停编辑和保存。请保持页面打开并重新加载。</p>
  <p v-if="storageStatus==='UNAVAILABLE'||storageStatus==='INVALID'" role="alert">本地恢复记录未保存，刷新或关闭页面可能丢失修改。</p>
  <p v-if="error" role="alert">{{error}}</p>
  <p v-if="unresolved" role="status">原操作结果尚未确认，请重试原请求。新操作需等待该结果。</p>
  <p v-if="state==='ACKNOWLEDGED'" role="status">已收到原操作成功回执，当前保存内容以重新读取的结果为准。</p>
  <p v-if="conflict" role="alert">服务器已有新版本。本地草稿已保留，请比较已保存信息后选择如何处理。</p>
  <section v-if="conflict&&conflictValue" class="conflict-preview" aria-label="最新保存版本">
   <h3>最新保存版本 · {{conflictToken}}</h3><dl><dt>会议名称</dt><dd>{{conflictValue.name??'未填写'}}</dd><dt>会议日期</dt><dd>{{conflictValue.occurredOn??'未填写'}}</dd><dt>会议分类</dt><dd>{{conflictValue.category??'未填写'}}</dd><dt>会议摘要</dt><dd>{{conflictValue.summary??'未填写'}}</dd><dt>最新名单草稿（企业身份）</dt><dd>{{conflictValue.rosterDraftIds.join('、')||'无'}}</dd><dt>最新外部人员草稿</dt><dd>{{(conflictValue.externalRosterNames??[]).join('、')||'无'}}</dd></dl>
  </section>
  <fieldset :disabled="blocked||busy"><legend class="sr-only">会议信息与名单草稿</legend>
   <label>会议名称 <span class="required">*</span><input aria-label="会议名称" placeholder="请输入会议名称，可在最终确认前补充" :value="value.name??''" @input="input('name',$event)"></label>
   <div class="info-columns"><label>会议日期 <span class="required">*</span><input aria-label="会议日期" aria-required="true" type="date" :value="value.occurredOn??''" @input="input('occurredOn',$event)"></label>
    <label>会议分类 <span class="required">*</span><select aria-label="会议分类" :value="value.category??''" @change="input('category',$event)"><option value="">请选择会议分类</option><option v-if="value.category&&!categories.some(c=>c.id===value.category)" :value="value.category">{{value.category}}（已选）</option><option v-for="category in categories" :key="category.id" :value="category.id">{{category.label}}</option></select></label></div>
   <button v-if="categoryMore" type="button" class="btn sm" :disabled="optionsBusy" @click="emit('categories',true)">更多会议分类</button>
   <label>会议摘要<textarea aria-label="会议摘要" placeholder="请输入会议摘要" rows="3" :value="value.summary??''" @input="input('summary',$event)"></textarea></label>
   <label class="form-label">参会人</label><div class="ac-participant-box"><span v-for="id in value.rosterDraftIds" :key="id" class="ac-participant-tag" :title="id">{{people.find(p=>p.stableId===id)?.displayName??rosterNames?.[id]??id}}<button type="button" :aria-label="'移除 '+id" @click="update('rosterDraftIds',value.rosterDraftIds.filter(x=>x!==id))">×</button></span><span v-for="(name,index) in value.externalRosterNames??[]" :key="'guest-'+index" class="ac-participant-tag">{{name}}<button type="button" :aria-label="'移除外部人员 '+name" @click="update('externalRosterNames',(value.externalRosterNames??[]).filter((_,i)=>i!==index))">×</button></span><span v-if="!value.rosterDraftIds.length&&!(value.externalRosterNames??[]).length" class="small muted">暂未添加参会人</span></div><div class="people-links"><button type="button" class="btn sm ghost" @click="peopleDialog?.showModal()">添加参会人</button><button type="button" class="btn sm ghost" disabled title="TXT没有发言人身份">从发言人获取</button></div><p class="small muted">保存名单草稿后，需最终确认时确认名单并更新参会权限。</p><div v-if="presentation!=='final'&&canConfirm&&!dirty" class="roster-confirm"><p class="small muted">保存后的名单才会更新参会权限。</p><button type="button" class="btn" :disabled="busy||blocked||unresolved" @click="emit('confirm')">确认已保存名单</button></div>
   <dialog ref="peopleDialog" class="people-dialog" aria-labelledby="people-dialog-title"><header class="between"><h3 id="people-dialog-title">添加参会人</h3><button type="button" class="btn sm ghost" @click="peopleDialog?.close()">关闭</button></header>
   <div class="tabs" role="tablist" aria-label="人员类型"><button type="button" class="tab" role="tab" :class="{active:peopleTab==='internal'}" :aria-selected="peopleTab==='internal'" @click="peopleTab='internal'">内部人员</button><button type="button" class="tab" role="tab" :class="{active:peopleTab==='external'}" :aria-selected="peopleTab==='external'" @click="peopleTab='external'">外部人员</button></div><section v-show="peopleTab==='internal'"><label>部门<select disabled aria-label="部门"><option>全部部门（部门筛选尚未接入）</option></select></label>
   <div class="actions"><label class="grow">搜索企业人员<input v-model="query" placeholder="姓名或企业身份"></label><button type="button" class="btn" :disabled="optionsBusy" @click="emit('search',query)">搜索人员</button></div>
   <ul class="selected"><li v-for="person in people" :key="person.stableId"><span>{{person.displayName}} · {{person.department??'部门未提供'}} <small>{{person.stableId}}</small></span><button type="button" class="btn" :disabled="!person.active||value.rosterDraftIds.includes(person.stableId)" @click="addPerson(person)">{{person.active?'加入名单':'已停用'}}</button></li></ul>
   <button v-if="peopleMore" type="button" class="btn" :disabled="optionsBusy" @click="emit('people',query)">下一页人员</button>
   <p v-if="optionsError" role="alert">{{optionsError}}</p>
   </section><section v-show="peopleTab==='external'"><label>外部机构<input placeholder="外部机构字段尚未接入" disabled/></label>
   <div class="actions"><label class="grow">外部参会人员<input v-model="external" placeholder="外部人员姓名，不授予系统访问权限"></label><button type="button" class="btn" @click="addExternal">添加外部人员</button></div>
   <ul class="selected"><li v-for="(name,index) in value.externalRosterNames??[]" :key="index">{{name}}<button type="button" class="btn" @click="update('externalRosterNames',(value.externalRosterNames??[]).filter((_,i)=>i!==index))">移除</button></li></ul>
</section><div class="actions"><span class="small muted">已选 {{value.rosterDraftIds.length+(value.externalRosterNames??[]).length}} 人</span><button type="button" class="btn primary" @click="peopleDialog?.close()">完成选择</button></div></dialog>
  </fieldset>
  <div v-if="presentation!=='final'" class="actions ac-info-drawer-footer"><button class="btn" :disabled="busy||blocked||unresolved" @click="emit('close')">取消</button><button v-if="unresolved" class="btn btn-primary" :disabled="busy||blocked" @click="emit('retry')">重试原请求</button><button v-else class="btn btn-primary" :disabled="busy||blocked||conflict||state==='CONFLICT'||state==='REJECTED'" @click="emit('save')">保存</button></div>
  <div v-if="conflict||state==='CONFLICT'||state==='REJECTED'" class="actions"><button v-if="conflict" class="btn" :disabled="busy||unresolved||blocked" @click="emit('reapply')">保留草稿并应用到最新版本</button><button class="btn" :disabled="busy||unresolved||blocked" @click="emit('discard')">放弃本地修改</button></div>
 </section>
</template>
<style scoped>
.info-editor h2{display:none}.info-editor{padding-bottom:110px}.info-editor fieldset{border:0;padding:0;min-width:0}.info-editor label{display:block;font-size:12px;color:var(--muted);margin-bottom:16px}.info-editor input,.info-editor textarea,.info-editor select{display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:8px 12px;border:1px solid var(--border2);border-radius:9px;font:inherit;font-size:13px;line-height:normal;color:var(--text);background:white}.info-editor textarea{resize:vertical}.info-columns{display:block}.required{color:var(--red);margin-left:3px}.ac-participant-box{display:flex;flex-wrap:wrap;gap:12px;padding:16px 12px 12px;min-height:70px;border:1px solid var(--border2);border-radius:6px}.ac-participant-tag{position:relative;display:inline-flex;padding:3px 10px;background:var(--orange-bg);border:1px solid #ffd5bc;border-radius:5px;color:var(--orange);font-size:12px}.ac-participant-tag>button{position:absolute;right:-6px;top:-6px;width:16px;height:16px;border-radius:50%;background:#fff;border:1px solid var(--border);cursor:pointer}.people-links{display:flex;margin:8px 0}.people-links .btn{padding-left:0;color:var(--orange)}.roster-confirm{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:12px 0 18px;padding:12px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px}.roster-confirm p{margin:0}.ac-info-drawer-footer{position:absolute;bottom:0;left:0;right:0;display:flex;align-items:center;justify-content:flex-end;gap:10px;padding:16px 20px;background:white;border-top:1px solid var(--border);z-index:2}.ac-info-drawer-footer .btn-primary{order:5}.info-editor [role=alert]{margin:10px 0;color:#9a3412}.info-editor [role=status]{margin:8px 0;font-size:12px;color:var(--muted)}.people-dialog{margin:auto;width:min(600px,calc(100vw - 40px));max-height:80vh;overflow:auto;padding:24px;border:1px solid var(--border);border-radius:10px;color:var(--text)}.people-dialog::backdrop{background:#11184955}.people-dialog .actions{display:flex;gap:10px;align-items:end;margin:14px 0}.people-dialog .grow{flex:1;margin:0}.selected{list-style:none;padding:0}.selected li{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:12px 0}.conflict-preview{padding:14px;background:#fff7ed}.conflict-preview dd{overflow-wrap:anywhere}.muted{color:var(--muted)}
</style>

<style scoped>.info-editor-final{padding-bottom:0}</style>
